from vpython import *

sun = sphere(pos=vector(0, 0, 0), radius=69.6, color=vec(1, 1, 0))
mercury = sphere(pos=vector(100.00, 0, 0), radius=2.439, color=vec(0.5, 0.5, 0.5))
venus = sphere(pos=vector(120.00, 0, 0), radius=6.051, color=vec(1, 0.7, 0.1))
earth = sphere(pos=vector(140.00, 0, 0), radius=6.371, color=vec(0, 0, 1))
jupiter = sphere(pos=vector(250.00, 0, 0), radius=15.5, color=vec(0.8, 0.5, 0.1))
saturn = sphere(pos=vector(280.00, 0, 0), radius=8.2, color=vec(0.9, 0.9, 0.7))

def checkbox_event(checkbox):
    if checkbox.checked:
        if checkbox.text == 'Mercury':
            mercury.visible = True
        elif checkbox.text == 'Venus':
            venus.visible = True
        elif checkbox.text == 'Earth':
            earth.visible = True
        elif checkbox.text == 'Jupiter':
            jupiter.visible = True
        elif checkbox.text == 'Saturn':
            saturn.visible = True
    else:
        if checkbox.text == 'Mercury':
            mercury.visible = False
        elif checkbox.text == 'Venus':
            venus.visible = False
        elif checkbox.text == 'Earth':
            earth.visible = False
        elif checkbox.text == 'Jupiter':
            jupiter.visible = False
        elif checkbox.text == 'Saturn':
            saturn.visible = False

# Create the checkbox widgets
checkbox1 = checkbox(pos=scene.title_anchor, text='Mercury', checked=True, bind=checkbox_event)
checkbox2 = checkbox(pos=scene.title_anchor, text='Venus', checked=True, bind=checkbox_event)
checkbox3 = checkbox(pos=scene.title_anchor, text='Earth', checked=True, bind=checkbox_event)
checkbox4 = checkbox(pos=scene.title_anchor, text='Jupiter', checked=True, bind=checkbox_event)
checkbox5 = checkbox(pos=scene.title_anchor, text='Saturn', checked=True, bind=checkbox_event)

while True:
    rate(60)
    mercury.rotate(angle=0.012, axis=vector(0, 1, 0), origin=sun.pos)
    venus.rotate(angle=0.031, axis=vector(0, 1, 0), origin=sun.pos)
    earth.rotate(angle=0.05, axis=vector(0, 1, 0), origin=sun.pos)
    jupiter.rotate(angle=0.004, axis=vector(0, 1, 0), origin=sun.pos)
    saturn.rotate(angle=0.009, axis=vector(0, 1, 0), origin=sun.pos)
